package com.opensocket.aievent.core.iam.token.application.service;
import com.opensocket.aievent.core.iam.security.contract.*;import com.opensocket.aievent.core.iam.token.application.command.*;import com.opensocket.aievent.core.iam.token.application.port.in.AccessTokenCommandPort;import com.opensocket.aievent.core.iam.token.application.port.out.*;import com.opensocket.aievent.core.iam.token.application.result.*;import com.opensocket.aievent.core.iam.token.domain.*;import com.opensocket.aievent.core.iam.token.event.TokenDomainEvent;import java.time.*;import java.util.*;
public final class AccessTokenApplicationService implements AccessTokenCommandPort {
 private final AccessTokenRepository tokens;private final ServiceAccountRepository accounts;private final TokenSecretPort secrets;private final TokenPermissionAuthorityPort authority;private final TokenSecurityEpochPort epochs;private final TokenPolicyRepository policies;private final TokenRateLimitPort rates;private final TokenEventPublisher events;private final TokenUsageEvidencePort usage;private final Clock clock;
 public AccessTokenApplicationService(AccessTokenRepository tokens,ServiceAccountRepository accounts,TokenSecretPort secrets,TokenPermissionAuthorityPort authority,TokenSecurityEpochPort epochs,TokenPolicyRepository policies,TokenRateLimitPort rates,TokenEventPublisher events,TokenUsageEvidencePort usage,Clock clock){this.tokens=tokens;this.accounts=accounts;this.secrets=secrets;this.authority=authority;this.epochs=epochs;this.policies=policies;this.rates=rates;this.events=events;this.usage=usage;this.clock=clock;}
 public ResolvedPersonalAccessTokenTenantResult resolvePersonalTenant(ResolvePersonalAccessTokenTenantCommand c){Parsed presented=parse(c.presentedToken());if(!presented.prefix().startsWith("odp_pat_"))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TYPE_MISMATCH,"Expected a personal access token");String tenant=tokens.findPersonalTenantByPrefix(presented.prefix()).orElseThrow(()->new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Invalid token"));return new ResolvedPersonalAccessTokenTenantResult(tenant,presented.prefix());}
 public IssuedTokenResult issuePersonal(IssuePersonalAccessTokenCommand c){PrincipalRef p=new PrincipalRef(PrincipalRef.PrincipalType.USER,c.userId());authority.requireActivePrincipal(c.tenantId(),p);return issue(c.tenantId(),p,AccessTokenType.PERSONAL_ACCESS_TOKEN,c.name(),c.scope(),c.ttl(),policies.effectivePolicy(c.tenantId()).maxActivePersonalTokens(),null,c.actorId(),c.correlationId());}
 public IssuedTokenResult issueService(IssueServiceAccountTokenCommand c){Instant now=clock.instant();ServiceAccount a=requireIssuableServiceAccount(c.tenantId(),c.serviceAccountId(),now);TokenScope merged=restrict(c.scope(),a.restrictions());Duration ttl=c.ttl()==null?a.tokenMaxTtl():min(c.ttl(),a.tokenMaxTtl());PrincipalRef p=new PrincipalRef(PrincipalRef.PrincipalType.SERVICE_ACCOUNT,c.serviceAccountId());authority.requireActivePrincipal(c.tenantId(),p);return issue(c.tenantId(),p,AccessTokenType.SERVICE_ACCOUNT_TOKEN,c.name(),merged,ttl,a.maxActiveTokens(),a,c.actorId(),c.correlationId());}
 public IssuedTokenResult issueOneTime(IssueOneTimeTokenCommand c){if(c.type()==null||!c.type().oneTime())throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TYPE_MISMATCH,"Expected one-time token type");PrincipalRef p=new PrincipalRef(PrincipalRef.PrincipalType.USER,c.userId());authority.requireEligibleOneTimeSubject(c.tenantId(),p,c.type());String permission=switch(c.type()){case INVITATION_TOKEN->"identity.user.activate";case PASSWORD_RESET_TOKEN->"identity.user.password.reset";case EMAIL_VERIFICATION_TOKEN->"identity.user.email.verify";default->throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TYPE_MISMATCH,"Unsupported one-time type");};return issue(c.tenantId(),p,c.type(),c.type().name(),TokenScope.oneTime(permission),c.ttl(),3,null,c.actorId(),c.correlationId());}
 public IssuedTokenResult rotate(RotateAccessTokenCommand c){AccessToken old=find(c.tenantId(),c.tokenId());Instant now=clock.instant();old.assertUsable(now);if(old.status()!=AccessTokenStatus.ACTIVE)throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_ROTATION_CONFLICT,"Only an active token can be rotated");if(old.type().oneTime())throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TYPE_MISMATCH,"One-time tokens cannot be rotated");Duration overlap=c.overlap()==null?Duration.ZERO:c.overlap();if(overlap.isNegative()||overlap.compareTo(Duration.ofMinutes(15))>0)throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_ROTATION_CONFLICT,"Rotation overlap must be between zero and 15 minutes");authority.requireActivePrincipal(old.tenantId(),old.principal());SecurityEpoch current=epochs.current(old.tenantId(),old.principal());if(!current.equals(old.securityEpoch()))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_SECURITY_EPOCH_STALE,"Token is no longer current after a security or permission change. Issue a new token using the current credential; stale tokens cannot be rotated.");TokenPolicy policy=policies.effectivePolicy(old.tenantId());ServiceAccount account=null;int maxActive=policy.maxActivePersonalTokens();TokenScope scope=old.scope();if(old.type()==AccessTokenType.SERVICE_ACCOUNT_TOKEN){account=requireIssuableServiceAccount(old.tenantId(),old.principal().principalId(),now);scope=restrict(old.scope(),account.restrictions());maxActive=account.maxActiveTokens();}Duration remaining=Duration.between(now,old.expiresAt());if(remaining.isZero()||remaining.isNegative())throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_EXPIRED,"Token is expired");if(overlap.isZero()){AccessToken revoked=old.revoke(c.actorId(),"ROTATED",now);tokens.save(revoked,old.version());publish("TOKEN_REVOKED",revoked,c.actorId(),c.correlationId(),TokenReasonCode.AUTH_TOKEN_REVOKED.name(),Map.of("rotation","true"));}IssuedTokenResult result=issue(old.tenantId(),old.principal(),old.type(),old.name(),scope,remaining,maxActive,account,c.actorId(),c.correlationId(),old.tokenId().value());if(!overlap.isZero()){AccessToken rotating=old.beginRotation(now.plus(overlap));tokens.save(rotating,old.version());}publish("TOKEN_ROTATED",old,c.actorId(),c.correlationId(),"",Map.of("replacementTokenId",result.tokenId(),"overlapSeconds",Long.toString(overlap.toSeconds())));return result;}
 public void revoke(RevokeAccessTokenCommand c){AccessToken old=find(c.tenantId(),c.tokenId());AccessToken revoked=old.revoke(c.actorId(),c.reason(),clock.instant());tokens.save(revoked,old.version());publish("TOKEN_REVOKED",revoked,c.actorId(),c.correlationId(),TokenReasonCode.AUTH_TOKEN_REVOKED.name(),Map.of());}
 public ValidatedTokenResult validate(ValidateAccessTokenCommand c){Parsed presented=parse(c.presentedToken());AccessToken token=tokens.findByPrefix(c.tenantId(),presented.prefix()).orElseThrow(()->new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Invalid token"));Instant now=clock.instant();try{token.assertUsable(now);if(!token.tenantId().equals(c.tenantId()))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TENANT_MISMATCH,"Token tenant mismatch");if(!secrets.matches(presented.secret(),token.secretHash()))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Invalid token");if(!token.scope().permitsAudience(c.audience()))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_AUDIENCE_DENIED,"Audience denied");if(!token.scope().permitsApiPath(c.apiPath()))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_API_PREFIX_DENIED,"API prefix denied");if(!token.scope().permitsIp(c.sourceIp()))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_CIDR_DENIED,"CIDR denied");if(token.type().oneTime())authority.requireEligibleOneTimeSubject(token.tenantId(),token.principal(),token.type());else authority.requireActivePrincipal(token.tenantId(),token.principal());SecurityEpoch current=epochs.current(token.tenantId(),token.principal());if(!current.isAtLeast(token.securityEpoch())||!token.securityEpoch().isAtLeast(current))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_SECURITY_EPOCH_STALE,"Token is no longer current after a security or permission change. Issue a new token using the current credential; stale tokens cannot be rotated.");int limit=token.type()==AccessTokenType.SERVICE_ACCOUNT_TOKEN?accounts.find(token.tenantId(),new ServiceAccountId(token.principal().principalId())).map(ServiceAccount::rateLimitPerMinute).orElse(1):600;String rateKey=token.type()==AccessTokenType.SERVICE_ACCOUNT_TOKEN?"service-account:"+token.principal().principalId():"token:"+token.tokenId().value();if(!rates.tryAcquire(token.tenantId(),rateKey,limit,now))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_RATE_LIMITED,"Token rate limited");Set<String> effective=authority.effectivePermissions(token.tenantId(),token.principal());TokenScope scope=token.scope().intersectPermissions(effective);if(!token.type().oneTime()&&scope.permissions().isEmpty())throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_SCOPE_INSUFFICIENT,"No effective token permissions");AccessToken used=token.used(now);tokens.save(used,token.version());usage.append(UUID.randomUUID().toString(),used,"ALLOW","",c.audience(),c.apiPath(),c.sourceIp(),now,c.correlationId());return new ValidatedTokenResult(token.tokenId().value(),token.type(),token.principal(),token.tenantId(),scope,current,token.issuedAt(),token.expiresAt());}catch(TokenDomainException e){usage.append(UUID.randomUUID().toString(),token,"DENY",e.reasonCode().name(),c.audience(),c.apiPath(),c.sourceIp(),now,c.correlationId());throw e;}}
 public ValidatedTokenResult consumeOneTime(ConsumeOneTimeTokenCommand c){ValidatedTokenResult v=validate(new ValidateAccessTokenCommand(c.presentedToken(),c.tenantId(),"opendispatch-iam","/api/session/token/consume",c.sourceIp(),c.correlationId()));if(v.type()!=c.expectedType()||!v.type().oneTime())throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TYPE_MISMATCH,"One-time token type mismatch");AccessToken old=find(c.tenantId(),v.tokenId());AccessToken consumed=old.consume(clock.instant());tokens.save(consumed,old.version());publish("TOKEN_CONSUMED",consumed,old.principal().principalId(),c.correlationId(),"",Map.of());return v;}
 private IssuedTokenResult issue(String tenant,PrincipalRef principal,AccessTokenType type,String name,TokenScope scope,Duration ttl,int maxActive,ServiceAccount account,String actor,String correlation){return issue(tenant,principal,type,name,scope,ttl,maxActive,account,actor,correlation,"");}
 private IssuedTokenResult issue(String tenant,PrincipalRef principal,AccessTokenType type,String name,TokenScope scope,Duration requestedTtl,int maxActive,ServiceAccount account,String actor,String correlation,String rotatedFrom){Instant now=clock.instant();TokenPolicy policy=policies.effectivePolicy(tenant);Duration max=type==AccessTokenType.SERVICE_ACCOUNT_TOKEN&&account!=null?min(policy.serviceMaxTtl(),account.tokenMaxTtl()):policy.maximumFor(type);Duration ttl=requestedTtl==null?policy.defaultFor(type):requestedTtl;if(ttl.isZero()||ttl.isNegative()||ttl.compareTo(max)>0)throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_TTL_EXCEEDED,"Token TTL exceeds policy");if(tokens.countActive(tenant,principal,type)>=maxActive)throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_ACTIVE_LIMIT_EXCEEDED,"Active token limit exceeded");Set<String> permissions=authority.effectivePermissions(tenant,principal);if(!type.oneTime())scope.requireSubsetOf(permissions);if(type==AccessTokenType.PERSONAL_ACCESS_TOKEN&&scope.permissions().stream().anyMatch(x->x.startsWith("instance.")))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_SCOPE_INSUFFICIENT,"Personal access tokens are Tenant-bound and cannot contain Instance permissions");if(principal.principalType()==PrincipalRef.PrincipalType.SERVICE_ACCOUNT&&scope.permissions().stream().anyMatch(x->x.startsWith("instance.")))throw new TokenDomainException(TokenReasonCode.SERVICE_ACCOUNT_INSTANCE_PERMISSION_FORBIDDEN,"Service accounts cannot receive instance permissions");TokenSecretPort.GeneratedSecret s=secrets.generate(type);SecurityEpoch epoch=epochs.current(tenant,principal);AccessToken token=AccessToken.issue(tenant,new TokenId(s.tokenId()),type,principal,name,s.publicPrefix(),s.last4(),s.hash(),scope,now,now.plus(ttl),epoch,rotatedFrom);tokens.save(token,0);publish("TOKEN_CREATED",token,actor,correlation,"",Map.of("type",type.name()));return new IssuedTokenResult(token.tokenId().value(),s.fullToken(),type,token.prefix(),token.last4(),token.expiresAt(),scope);}
 private AccessToken find(String tenant,String id){return tokens.findById(tenant,new TokenId(id)).orElseThrow(()->new TokenDomainException(TokenReasonCode.AUTH_TOKEN_NOT_FOUND,"Token not found"));}
 private void publish(String type,AccessToken t,String actor,String correlation,String reason,Map<String,String> metadata){events.publish(new TokenDomainEvent(UUID.randomUUID().toString(),type,t.tenantId(),t.principal().principalType().name(),t.principal().principalId(),t.tokenId().value(),actor,correlation,reason,clock.instant(),metadata));}
 private ServiceAccount requireIssuableServiceAccount(String tenantId,String serviceAccountId,Instant now){ServiceAccount a=accounts.find(tenantId,new ServiceAccountId(serviceAccountId)).orElseThrow(()->new TokenDomainException(TokenReasonCode.SERVICE_ACCOUNT_NOT_FOUND,"Service account not found"));if(a.status()==ServiceAccountStatus.SUSPENDED_RISK)throw new TokenDomainException(TokenReasonCode.SERVICE_ACCOUNT_RISK_SUSPENDED,"Service account is risk suspended");if(a.status()==ServiceAccountStatus.OWNERSHIP_REVIEW||!now.isBefore(a.nextReviewAt()))throw new TokenDomainException(TokenReasonCode.SERVICE_ACCOUNT_OWNERSHIP_REVIEW_REQUIRED,"Ownership review is required");if(a.status()!=ServiceAccountStatus.ACTIVE)throw new TokenDomainException(TokenReasonCode.SERVICE_ACCOUNT_INVALID_STATUS,"Service account is not active");return a;}
 private TokenScope restrict(TokenScope requested,TokenScope allowed){Objects.requireNonNull(requested,"requested scope");Objects.requireNonNull(allowed,"allowed scope");Set<String> permissions=requested.permissions().isEmpty()?allowed.permissions():requested.permissions();Set<String> audiences=requested.audiences().isEmpty()?allowed.audiences():requested.audiences();Set<String> prefixes=requested.apiPrefixes().isEmpty()?allowed.apiPrefixes():requested.apiPrefixes();Set<String> allowedCidrs=allowed.cidrs().stream().map(CidrBlock::notation).collect(java.util.stream.Collectors.toCollection(java.util.TreeSet::new));Set<String> requestedCidrs=requested.cidrs().stream().map(CidrBlock::notation).collect(java.util.stream.Collectors.toCollection(java.util.TreeSet::new));Set<String> cidrs=requestedCidrs.isEmpty()?allowedCidrs:requestedCidrs;if(permissions.isEmpty()||!allowed.permissions().containsAll(permissions))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_SCOPE_INSUFFICIENT,"Requested permissions exceed service account restriction");if(audiences.isEmpty()||!allowed.audiences().containsAll(audiences))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_AUDIENCE_DENIED,"Requested audience exceeds service account restriction");if(prefixes.isEmpty()||!allowed.apiPrefixes().containsAll(prefixes))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_API_PREFIX_DENIED,"Requested API prefix exceeds service account restriction");if(cidrs.isEmpty()||!allowedCidrs.containsAll(cidrs))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_CIDR_DENIED,"Requested CIDR exceeds service account restriction");return new TokenScope(permissions,audiences,prefixes,cidrs);}
 private static Duration min(Duration a,Duration b){return a.compareTo(b)<=0?a:b;}
 private record Parsed(String prefix,String secret){} private Parsed parse(String raw){if(raw==null||raw.isBlank())throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Token is required");String value=raw.trim();if(value.length()>160)throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Invalid token format");String[] parts=value.split("_",4);if(parts.length!=4||!"odp".equals(parts[0]))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Invalid token format");String prefix=String.join("_",parts[0],parts[1],parts[2]);if(!prefix.matches("odp_(pat|sat|invite|reset|verify)_[0-9a-f]{18}")||!parts[3].matches("[A-Za-z0-9_-]{43}"))throw new TokenDomainException(TokenReasonCode.AUTH_TOKEN_INVALID,"Invalid token format");return new Parsed(prefix,parts[3]);}
}
